    fprintf(out, "\"residencyStandard3DBlockShape\":%s,", s->residencyStandard3DBlockShape ? "true" : "false");
    fprintf(out, "\"residencyAlignedMipSize\":%s,", s->residencyAlignedMipSize ? "true" : "false");
