static void print_limits_and_sparse_json(FILE *out, const VkPhysicalDeviceLimits *l, const VkPhysicalDeviceSparseProperties *sp) {
    fprintf(out, "\"limits\":{");
    print_VkPhysicalDeviceLimits_json(out, l);
    fprintf(out, "},\"sparseProperties\":{");
    print_VkPhysicalDeviceSparseProperties_json(out, sp);
    fprintf(out, "}");
}

